create or replace function public.match_completion_log_rows() returns jsonb language plpgsql security definer set search_path to 'public' as $fn$ declare r record; c int; v_job uuid; v_method text; v_note text; n_m int := 0; n_a int := 0; n_u int := 0; begin if auth.uid() is not null and not public.is_admin() then raise exception 'office only' using errcode = '42501'; end if; for r in select * from public.completion_log_rows where match_status in ('unmatched', 'ambiguous') order by date_completed nulls last, received_at loop v_job := null; v_method := null; v_note := null; if r.ghl_project_id is not null then select id into v_job from public.jobs where ghl_project_display_id = r.ghl_project_id order by created_at limit 1; if v_job is not null then v_method := 'ghl_project_id'; end if; end if; if v_job is null then select count(*) into c from public.jobs j where public.address_key(j.customer_address) = public.address_key(r.address); if c = 1 then select id into v_job from public.jobs j where public.address_key(j.customer_address) = public.address_key(r.address); v_method := 'address'; elsif c > 1 then select min(id::text)::uuid into v_job from public.jobs j where public.address_key(j.customer_address) = public.address_key(r.address) and abs(coalesce(j.contract_amount, 0) - coalesce(r.contract_amount, -1)) < 1 having count(*) = 1; if v_job is not null then v_method := 'address+amount'; else v_note := c || ' jobs at this address and no single contract-amount match'; end if; end if; end if; if v_job is null and v_note is null then select min(id::text)::uuid into v_job from public.jobs j where public.house_no(j.customer_address) = public.house_no(r.address) and public.last_name(j.customer_name) = public.last_name(r.customer) having count(*) = 1; if v_job is not null then v_method := 'house_no+last_name'; end if; end if; if v_job is null and v_note is null then select min(id::text)::uuid into v_job from public.jobs j where public.last_name(j.customer_name) = public.last_name(r.customer) and abs(coalesce(j.contract_amount, 0) - coalesce(r.contract_amount, -1)) < 1 having count(*) = 1; if v_job is not null then v_method := 'last_name+amount'; end if; end if; if v_job is null and v_note is null then select min(id::text)::uuid into v_job from public.jobs j where public.norm_person(j.customer_name) = public.norm_person(r.customer) and (coalesce(j.contract_amount, 0) = 0 or abs(j.contract_amount - coalesce(r.contract_amount, 0)) <= 0.15 * j.contract_amount) and not exists (select 1 from public.completion_log_rows o where o.job_id = j.id and o.id <> r.id and public.address_key(o.address) is distinct from public.address_key(r.address)) having count(*) = 1; if v_job is not null then v_method := 'full_name_only'; end if; end if; if v_job is not null then update public.completion_log_rows set job_id = v_job, match_method = v_method, match_status = 'matched', match_note = null where id = r.id; n_m := n_m + 1; elsif v_note is not null then update public.completion_log_rows set match_status = 'ambiguous', match_note = v_note where id = r.id; n_a := n_a + 1; else update public.completion_log_rows set match_status = 'unmatched', match_note = 'no job at this address or with this name' where id = r.id; n_u := n_u + 1; end if; end loop; return jsonb_build_object('matched', n_m, 'ambiguous', n_a, 'unmatched', n_u); end $fn$;;
